import{_ as t,E as i,o as n,a as l,d as a,H as r}from"./chunks/framework.MWxrmMMs.js";const b=JSON.parse('{"title":"Установка","description":"Подробная инструкция по установке Stuzhik на Windows и Linux. Системные требования, пакеты AppImage, .deb и .rpm, обновление и удаление.","frontmatter":{"description":"Подробная инструкция по установке Stuzhik на Windows и Linux. Системные требования, пакеты AppImage, .deb и .rpm, обновление и удаление.","head":[["meta",{"name":"keywords","content":"stuzhik скачать, установить stuzhik, стужик, minecraft launcher download, системные требования"}]]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),s={name:"guide/installation.md"};function d(u,o,h,p,c,g){const e=i("DownloadButton");return n(),l("div",null,[o[0]||(o[0]=a('<h1 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h1><h2 id="системные-требования" tabindex="-1">Системные требования <a class="header-anchor" href="#системные-требования" aria-label="Permalink to &quot;Системные требования&quot;">​</a></h2><h3 id="минимальные" tabindex="-1">Минимальные <a class="header-anchor" href="#минимальные" aria-label="Permalink to &quot;Минимальные&quot;">​</a></h3><ul><li><strong>RAM:</strong> 4GB (рекомендуется 8GB)</li><li><strong>Место на диске:</strong> 2GB + место под экземпляры</li><li><strong>ОС:</strong> Windows 10+ или Linux x86_64 с glibc 2.38+ (Debian 13, Ubuntu 24.04, Fedora 39 и новее)</li></ul><h3 id="рекомендуемые" tabindex="-1">Рекомендуемые <a class="header-anchor" href="#рекомендуемые" aria-label="Permalink to &quot;Рекомендуемые&quot;">​</a></h3><ul><li><strong>RAM:</strong> 16GB</li><li><strong>Место на диске:</strong> SSD с 20GB свободного места</li><li><strong>GPU:</strong> Любая с поддержкой OpenGL 3.3+</li></ul><h2 id="скачать" tabindex="-1">Скачать <a class="header-anchor" href="#скачать" aria-label="Permalink to &quot;Скачать&quot;">​</a></h2>',7)),r(e),o[1]||(o[1]=a('<ol><li>Скачай установщик кнопкой выше</li><li>Запусти скачанный установщик</li><li>Следуй инструкциям установщика</li></ol><p>Для Linux есть AppImage, .deb и .rpm: <a href="/download.html#linux">Скачать</a>, как их ставить и обновлять, описано <a href="#linux">ниже</a>. Для серверов на Linux есть <a href="/guide/cli.html">консольная версия</a>.</p><h2 id="обновление" tabindex="-1">Обновление <a class="header-anchor" href="#обновление" aria-label="Permalink to &quot;Обновление&quot;">​</a></h2><p>Stuzhik проверяет обновления автоматически при запуске и сам ставит найденную версию.</p><p>Настроить: Настройки → &quot;Обновления&quot;:</p><ol><li>&quot;Проверять обновления при запуске&quot; — выключи, если автообновление не нужно</li><li>&quot;Канал обновлений&quot; — &quot;Стабильный&quot; или &quot;Бета&quot;</li></ol><p>Проверить вручную — там же, строка &quot;Проверить сейчас&quot; → кнопка &quot;Проверить обновления&quot;. Можно и просто скачать новый установщик и запустить поверх старого: сборки, миры и настройки останутся.</p><h2 id="деинсталляция" tabindex="-1">Деинсталляция <a class="header-anchor" href="#деинсталляция" aria-label="Permalink to &quot;Деинсталляция&quot;">​</a></h2><p>Удаляется как обычная программа: Параметры Windows → Приложения → Stuzhik → Удалить.</p><p>Что уходит при удалении:</p><ul><li><strong>Всегда</strong> — служебное: кэш, логи, отчёты об ошибках, данные встроенного браузера, сохранённые входы в аккаунты (они лежат в диспетчере учётных данных Windows) и правило брандмауэра для Stuzhik Connect. Чтобы снять правило, Windows один раз попросит подтверждение администратора — только если правило было создано</li><li><strong>Только с галочкой</strong> &quot;Удалить также сборки и миры (все данные лаунчера)&quot; — сборки, миры, настройки, Java и файлы игры. Без галочки они остаются, и после повторной установки всё на месте</li></ul><p>Обновление лаунчера ничего из этого не трогает.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux {#linux}&quot;">​</a></h2><p>Пакеты и для каких систем они: <a href="/download.html#linux">Скачать → Linux</a>. Нужны x86_64 и glibc 2.38 или новее (<code>ldd --version</code>).</p><ul><li><strong>Установка.</strong> AppImage: <code>chmod +x Stuzhik_*.AppImage</code> и запустить файл. .deb: <code>sudo apt install ./Stuzhik_*_amd64.deb</code>. .rpm: <code>sudo dnf install ./Stuzhik-*.x86_64.rpm</code> (openSUSE: <code>sudo zypper install</code>).</li><li><strong>Обновление.</strong> Как на Windows: лаунчер находит новую версию сам. AppImage он заменяет на месте, .deb и .rpm ставит система и один раз спрашивает пароль.</li><li><strong>Удаление.</strong> <code>sudo apt remove stuzhik</code> или <code>sudo dnf remove stuzhik</code>; AppImage просто удаляется. Сборки, миры и настройки остаются в <code>~/.local/share/ru.sibxodev.stuzhik</code>: удалите эту папку, если они больше не нужны.</li><li><strong>AppImage не запускается на Ubuntu 24.04.</strong> Нужна библиотека FUSE 2: <code>sudo apt install libfuse2t64</code>. Или запустите <code>./Stuzhik_*.AppImage --appimage-extract-and-run</code>.</li><li><strong>Ошибка «GLIBC_2.38 not found».</strong> Система старше нужной (Debian 12, Ubuntu 22.04): приложение на ней не запустится. Серверы на ней работают через <a href="/guide/cli.html">консольную версию</a>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="не-запускается" tabindex="-1">Не запускается <a class="header-anchor" href="#не-запускается" aria-label="Permalink to &quot;Не запускается&quot;">​</a></h3><p>Установи <a href="https://developer.microsoft.com/en-us/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 Runtime</a>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">winget</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> Microsoft.EdgeWebView2Runtime</span></span></code></pre></div>',19))])}const _=t(s,[["render",d]]);export{b as __pageData,_ as default};
